package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.graphics.*;import android.util.Base64;import org.json.*;import java.io.*;
/** Synthetic images and notes only. Exercises the actual Android WebView editor. */
public final class ImageSpacingTest extends DocumentEditorTest {
 String source()throws Exception{return new JSONArray("["+h.js("DocumentRich.serialize(document.querySelector('#doc-body'))")+"]").getString(0);}
 JSONObject picture(int n)throws Exception{Bitmap b=Bitmap.createBitmap(320,160,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(0xffd5e4c0+n*123);Paint p=new Paint();p.setColor(0xff216a54);p.setTextSize(30);c.drawText("Image "+n,20,90,p);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return (JSONObject)h.call("storeRecordImage",new JSONObject().put("data","data:image/png;base64,"+Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP)).put("name","合成图片"+n+".png"));}
 String token(JSONObject img)throws Exception{return "!["+img.getString("name")+"](zhishi-media:"+img.getString("id")+")";}
 void end()throws Exception{h.js("(()=>{const b=document.querySelector('#doc-body'),r=document.createRange();b.focus();r.selectNodeContents(b);r.collapse(false);getSelection().removeAllRanges();getSelection().addRange(r);document.dispatchEvent(new Event('selectionchange'));})()");}
 void insert(JSONObject img,int count)throws Exception{h.js("window.__insertError=null;RecordEditor.image("+img+").catch(e=>__insertError=e.message)");until("document.querySelectorAll('#doc-body .doc-image').length==="+count+"||!!__insertError");check(h.js("__insertError===null").equals("true"),"Image insertion completes without error");Thread.sleep(200);}
 @Override public void onStart(){Bundle result=new Bundle();try{
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  check(h.js("(()=>{const t=id=>'![image](zhishi-media:'+id.repeat(64)+')',a=t('a'),b=t('b');const cases=['前'+a+'后','前\\n'+a+'\\n后',a+'\\n'+b,a+'\\n\\n后',a+'\\n\\n\\n后',a+'\\n',a+b,'前\\n'+a+'\\n\\n'+b+'\\n后'];return cases.every(note=>{const box=document.createElement('div');box.id='doc-body';box.append(DocumentRich.render(note,id=>'<figure data-token=\"![image](zhishi-media:'+id+')\"><img alt=\"image\"></figure>'));return DocumentRich.serialize(box)===note})})()").equals("true"),"Source boundaries preserve zero / one / multiple line breaks and adjacent images without root snapshot");
  check(h.js("(()=>{const note='![image](zhishi-media:'+'a'.repeat(64)+')\\n正文',box=document.createElement('div');box.append(DocumentRich.render(note,id=>'<figure data-token=\"![image](zhishi-media:'+id+')\"></figure>'));return box.querySelectorAll('.rich-block').length===1&&box.querySelector('.rich-block').textContent==='正文'})()").equals("true"),"Single image separator does not render a phantom empty paragraph");
  JSONObject a=picture(1),b=picture(2),c=picture(3);String note="第一段正文。\n"+token(a)+"\n图片后的正文保持紧凑。\n\n原来刻意保留的空行段落。\n"+token(b)+"\n最后一段正文。";
  JSONObject r=new JSONObject().put("id","image-spacing-"+System.currentTimeMillis()).put("type","learning").put("date","2026-10-20").put("title","连续插图保持原排版").put("note",note).put("images",new JSONArray().put(a).put(b)).put("tags",new JSONArray()).put("durationMinutes",15);
  h.call("saveRecord",new JSONObject().put("record",r).put("allowDuplicate",true));runOnMainSync(()->h.activity.finish());h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{};RecordEditor.open("+record(r.getString("id"))+")");until("document.querySelectorAll('#doc-body img').length===2&&Array.from(document.querySelectorAll('#doc-body img')).every(i=>i.naturalWidth>0)");
  check(source().equals(note),"Opening historical image note preserves exact source");h.js("window.__gaps=Array.from(document.querySelectorAll('#doc-body .doc-image')).map(f=>f.nextElementSibling.getBoundingClientRect().top-f.getBoundingClientRect().bottom)");end();insert(c,3);
  String after=source();String suffix="\n"+token(c);check((after.endsWith(suffix)?after.substring(0,after.length()-suffix.length()):after.endsWith(token(c))?after.substring(0,after.length()-token(c).length()):after).equals(note),"Adding a new image leaves all old image/text separators byte-for-byte unchanged; source="+after);
  check(h.js("Array.from(document.querySelectorAll('#doc-body .doc-image')).slice(0,2).every((f,i)=>Math.abs(f.nextElementSibling.getBoundingClientRect().top-f.getBoundingClientRect().bottom-__gaps[i])<1)").equals("true"),"Existing image/text visual gaps do not grow after insertion");
  h.screenshot("image-spacing.png");String firstInsert=source();
  click("#doc-undo");check(source().equals(note),"Undo insertion restores original image placement and all original blank lines");click("#doc-redo");check(source().equals(firstInsert),"Redo insertion does not add any additional line breaks");
  JSONObject d=picture(4),f=picture(5);end();insert(d,4);String secondInsert=source();check(secondInsert.equals(firstInsert+"\n"+token(d)),"Second appended image changes only the new insertion boundary");end();insert(f,5);String thirdInsert=source();check(thirdInsert.equals(secondInsert+"\n"+token(f)),"Third appended image never accumulates spacing around old images");
  saveUI();JSONObject stored=record(r.getString("id"));check(stored.getString("note").equals(thirdInsert)&&stored.getJSONArray("images").length()==5,"Saving retains exact image/text source and all five attachments");h.js("RecordEditor.open("+stored+")");until("document.querySelectorAll('#doc-body img').length===5");check(source().equals(thirdInsert),"Saved image note reopens with identical text and image separators");
  // Insert inside one paragraph; the earlier images and deliberately blank paragraph must remain intact.
  h.js("(()=>{const b=document.querySelector('#doc-body'),w=document.createTreeWalker(b,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){const at=n.textContent.indexOf('最后一段');if(at>=0){const range=document.createRange();range.setStart(n,at+2);range.collapse(true);b.focus();getSelection().removeAllRanges();getSelection().addRange(range);document.dispatchEvent(new Event('selectionchange'));break;}}})()");JSONObject g=picture(6);insert(g,6);String middle=source();check(middle.startsWith(note.substring(0,note.indexOf("最后一段"))),"Middle-of-paragraph insertion preserves every preceding old image and intentional blank line");check(middle.contains("最"+"后")&&middle.contains("一段正文。"),"Inserting at caret preserves text on both sides of image");
  click("#doc-undo");check(source().equals(thirdInsert),"Undo middle insertion restores the complete saved source");close();
  result.putString("stream","PASS ImageSpacingTest: "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable err){try{if(h!=null)h.screenshot("image-spacing-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL ImageSpacingTest after "+passed+": "+err+" cause="+err.getCause()+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
